from robyn import Robyn, Request, Response, status_codes
import json

app = Robyn(__file__)

@app.get("/admin/workers/pools/:tenant_id/status")
async def get_worker_pool_status(request: Request):
    if not request.identity:
        return Response(status_code=status_codes.HTTP_401_UNAUTHORIZED, description="Unauthorized", headers={})

    tenant_id = request.path_params.get("tenant_id")
    caller_tenant = request.identity.claims.get("tenant_id")
    is_admin = request.identity.claims.get("is_admin", False)

    if caller_tenant != tenant_id and not is_admin:
        return Response(status_code=status_codes.HTTP_403_FORBIDDEN, description="Forbidden: Insufficient privileges", headers={})

    pool_stats = app.get_worker_pool_metrics(tenant_id)
    if not pool_stats:
        return Response(status_code=status_codes.HTTP_404_NOT_FOUND, description="Tenant pool not found", headers={})

    return Response(status_code=status_codes.HTTP_200_OK, description=json.dumps(pool_stats), headers={"Content-Type": "application/json"})
